mapper.select:
SELECT DPB.SETT_DATE lastSettDate FROM
	DIS_PROD_BONUSPLAN DPB
WHERE DPB.DATA_STATUS = 'E'
  AND DPB.PROD_ID = #{prodId,jdbcType=VARCHAR}
  AND DPB.SETT_DATE = (
	  select max(h.SETT_DATE) from DIS_PROD_BONUSPLAN h
	  where h.SETT_DATE < TO_DATE(#{baseDate},'yyyy-MM-dd')
		and h.PROD_ID = #{prodId,jdbcType=VARCHAR}
		and h.DATA_STATUS = 'E'
	)
